import { readFileSync } from "node:fs";

import { expect, test } from "@playwright/test";

// Scan a barcode from a photo: fixtures are generated by tests/fixtures/make_fixtures.py.

test("photo of grapefruit juice is decoded and checked", async ({ page }) => {
  await page.goto("/");
  await page.getByTestId("photo-input").setInputFiles("tests/fixtures/grapefruit-juice.jpg");
  await expect(page.getByTestId("photo-result")).toContainText("025000051753");
  await expect(page.getByTestId("product-title")).toContainText(/grapefruit/i);
});

test("photo of the recalled fan barcode is decoded and flagged", async ({ page }) => {
  await page.goto("/");
  await page.getByTestId("photo-input").setInputFiles("tests/fixtures/recalled-fan.png");
  await expect(page.getByTestId("photo-result")).toContainText("840059614922");
  await expect(page.getByTestId("recalled")).toBeVisible();
});

test("photo with no barcode shows a hint and runs no product check", async ({ page }) => {
  await page.goto("/");
  await page.getByTestId("photo-input").setInputFiles("tests/fixtures/no-barcode.jpg");
  const result = page.getByTestId("photo-result");
  await expect(result).toBeVisible();
  await expect(result).toHaveText(/\S/);
  await expect(page.getByTestId("product-title")).toHaveCount(0);
});

test("decode API reads the grapefruit juice photo", async ({ request }) => {
  const image = readFileSync("tests/fixtures/grapefruit-juice.jpg");
  const response = await request.post("/api/decode", {
    data: image,
    headers: { "Content-Type": "image/jpeg" },
  });
  expect(response.ok()).toBeTruthy();
  const body = await response.json();
  expect(body.found).toBe(true);
  expect(body.code).toMatch(/025000051753$/);
});
